        onChange={(e) => setReason(e.target.value)}
      />
      <button
        type="button"
        data-testid="claim-reject"
        disabled={busy}
        onClick={() => changeTo({ status: 'OPEN', review: true, reason })}
      >
        Reject
      </button>{' '}
      <select data-testid="claim-reassign-to" value={moveTo} onChange={(e) => setMoveTo(e.target.value)}>
        <option value="">Move to…</option>
        {(people.data ?? []).filter((p) => p.id !== claim.personId).map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={busy}
        onClick={() => {
          change.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          inline.reset();
          comment.reset();
          setRefused(undefined);
          reassign.mutate(moveTo);
        }}
      >
        Move
      </button>{' '}
      <button
        type="button"
        data-testid="claim-resettle"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          defer.reset();
          proof.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          inline.reset();
          comment.reset();
          setRefused(undefined);
          resettle.mutate();
        }}
      >
        Re-settle
      </button>{' '}
      Deferred <span data-testid="claim-deferred">{claim.deferred ? 'yes' : 'no'}</span>{' '}
      <span data-testid="claim-deferred-until">{claim.deferredUntil ?? ''}</span>{' '}
      <input
        type="date"
        data-testid="claim-defer-date"
        value={deferUntil}
        onChange={(e) => {
          setDeferUntil(e.target.value);
          defer.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-defer"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          proof.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          inline.reset();
          comment.reset();
          setRefused(undefined);
          defer.mutate(deferUntil);
        }}
      >
        Defer
      </button>{' '}
      Proofs <span data-testid="claim-proofs">{claim.proofs ?? 0}</span>{' '}
      <button
        type="button"
        data-testid="claim-proof"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          split.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          inline.reset();
          comment.reset();
          setRefused(undefined);
          proof.mutate();
        }}
      >
        Add proof
      </button>{' '}
      Split from <span data-testid="claim-split-from">{claim.splitFrom ?? ''}</span>{' '}
      <input
        data-testid="claim-split-amount"
        placeholder="Split amount"
        value={splitAmount}
        onChange={(e) => {
          setSplitAmount(e.target.value);
          split.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-split"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          redate.reset();
          lock.reset();
          remind.reset();
          inline.reset();
          comment.reset();
          setRefused(undefined);
          split.mutate(splitAmount);
        }}
      >
        Split
      </button>{' '}
      <input
        type="date"
        data-testid="claim-date-new"
        value={newDate}
        onChange={(e) => {
          setNewDate(e.target.value);
          redate.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-redate"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          split.reset();
          lock.reset();
          remind.reset();
          inline.reset();
          comment.reset();
          setRefused(undefined);
          redate.mutate(newDate);
        }}
      >
        Re-date
      </button>{' '}
      Reminded <span data-testid="claim-reminded">{claim.reminded ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="claim-remind"
        disabled={busy}
        onClick={() => {
          resetAll();
          remind.mutate();
        }}
      >
        Remind
      </button>{' '}
      <button
        type="button"
        data-testid="claim-edit"
        disabled={busy}
        onClick={() => {
          resetAll();
          const why = refusal();
          if (why === undefined) lock.mutate();
          else {
            setRefused(why);
            if (viewer()) openEditor();
          }
        }}
      >
        Edit
      </button>{' '}
      <input
        data-testid="claim-inline-amount"
        placeholder="Amount"
        inputMode="decimal"
        value={inlineAmount}
        onChange={(e) => {
          setInlineAmount(e.target.value);
          inline.reset();
          comment.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-inline-save"
        disabled={busy}
        onClick={() => {
          resetAll();
          inline.mutate(inlineAmount);
        }}
      >
        Save amount
      </button>{' '}
      <input
        data-testid="claim-comment-text"
        placeholder="Comment"
        value={commentText}
        onChange={(e) => {
          setCommentText(e.target.value);
          comment.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-comment-add"
        disabled={busy}
        onClick={() => {
          resetAll();
          comment.mutate(commentText);
        }}
      >
        Comment
      </button>
      {editingId === claim.id && (
        <button
          type="button"
          data-testid="claim-cancel"
          onClick={() => {
            resetAll();
            unlock(claim.id);
            setEditing(undefined);
          }}
        >
          Cancel
        </button>
      )}{' '}
      {error && (
        <span data-testid="claim-error" role="alert">
          {error.message}
        </span>
      )}
    </>
  );
}

